import React,{useEffect,useState,useRef} from 'react';
import {createRoot} from 'react-dom/client';
import {BookOpen,LayoutDashboard,Library,Settings,ArrowUpRight,ArrowRight,ChevronRight,ChevronLeft,Plus,Loader2,Send,X,FileText,Download,RefreshCw,KeyRound,ShieldCheck,Blocks,Fingerprint,Network,ScanLine,NotebookPen,Bookmark,Search,Menu,CheckCircle2,ExternalLink,Brain,GraduationCap,FolderOpen,Database,Bot,GitBranch,CircleHelp,MessageSquare,Pencil,Trash2,Sparkles,Calendar} from 'lucide-react';
import Markdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import '@fontsource/dm-sans/400.css';
import '@fontsource/dm-sans/500.css';
import '@fontsource/dm-sans/600.css';
import './style.css';

type Module={id:string;name:string;description:string;term:number;level:number;credits:number;occurrence:string;assessment:string;icon:string;elective?:boolean;sources:number};
type Source={id:string;module:string;title:string;kind:string;status:string;pages:number;created:string;warning:string;origin:string};
type Citation={source_id:string;title:string;page:number;text:string;ref:string;kind:string};
type Answer={answer:string;model:string;citations:Citation[];grounded:boolean;diagram:{title:string;nodes:string[];connections:{from:number;to:number;label:string}[]};quiz:{question:string;choices:string[];answer:number;explanation:string};followups:string[]};
type Message={id:number;role:string;content:{question?:string}&Partial<Answer>};
type ChatSession={id:string;scope:'module'|'global';module:string|null;title:string;created:string;updated:string};
type Job={id:string;module:string;url:string;status:string;detail:string};
type Bootstrap={token:string;modules:Module[];sources:Source[];progress:Record<string,boolean>;jobs:Job[];feeds:{id:string;module:string;url:string}[];model:{ready:boolean;model:string;detail:string;auth?:string};electives:Record<string,{id:string;name:string}[]>;selected_electives:Record<string,string>;data_path:string;source_path:string;dates:string[][];readings:Record<string,string[][]>;snapshot:string;notes_count:number;retrieval:string};
type View='overview'|'notebook'|'library'|'guide'|'notes'|'settings';
let token='';
async function api<T=any>(url:string,body?:unknown,method='POST'):Promise<T>{
 const response=await fetch(url,body===undefined?{}:{method,headers:{'X-Study-Token':token,...(!(body instanceof FormData)?{'Content-Type':'application/json'}:{})},body:body instanceof FormData?body:JSON.stringify(body)});
 if(!response.ok){let message='The request could not be completed.';try{const d=await response.json();message=typeof d.detail==='string'?d.detail:JSON.stringify(d.detail);}catch{}throw Error(message);}
 return response.json();
}
const icons:Record<string,React.ComponentType<{size?:number}>>={KeyRound,ShieldCheck,Blocks,Fingerprint,Network,ScanLine,NotebookPen,BookOpen,Brain,Database};
function Icon({name,size=20}:{name:string;size?:number}){const I=icons[name]||BookOpen;return <I size={size}/>;}
function Rich({text}:{text:string}){return <div className="prose"><Markdown remarkPlugins={[remarkGfm]} components={{a:({children,href})=><a href={href} target="_blank" rel="noreferrer">{children}</a>}}>{text}</Markdown></div>;}
function App(){
  const [data,setData]=useState<Bootstrap|null>(null),[view,setView]=useState<View>('overview'),[moduleId,setModuleId]=useState('7CCSMCIS'),[error,setError]=useState(''),[notice,setNotice]=useState(''),[sidebar,setSidebar]=useState(false),[source,setSource]=useState<{id:string;page:number}|null>(null),[openTerms,setOpenTerms]=useState<Record<string,boolean>>(()=>JSON.parse(localStorage.getItem('kcl-sidebar-terms')||'{"1":true,"2":true,"3":true}'));
 async function refresh(){try{const d=await api<Bootstrap>('/api/bootstrap');token=d.token;setData(d);}catch(e){setError(String((e as Error).message));}}
 useEffect(()=>{refresh();const timer=setInterval(refresh,10000);return ()=>clearInterval(timer);},[]);
 useEffect(()=>{if(notice){const t=setTimeout(()=>setNotice(''),6000);return ()=>clearTimeout(t);}},[notice]);
 const nav=(v:View)=>{setView(v);setSidebar(false);setError('');};
 const openModule=(id:string)=>{setModuleId(id);nav('notebook');};
 async function act(fn:()=>Promise<unknown>,success=''){try{await fn();if(success)setNotice(success);await refresh();}catch(e){setError((e as Error).message);}}
 if(!data)return <div className="loading-page"><BookOpen size={32}/><h1>Opening your study space</h1><p>{error||'Loading your local course library…'}</p>{error&&<button onClick={refresh}>Try again</button>}</div>;
 const current=data.modules.find(m=>m.id===moduleId)||data.modules[0];
 const navItems:[View,React.ComponentType<{size?:number}>,string][]=[['overview',LayoutDashboard,'My modules'],['library',Library,'Source library'],['notes',Bookmark,'Saved notes'],['guide',BookOpen,'Course guide']];
 return <div className="app-shell">
  {sidebar&&<button className="nav-scrim" aria-label="Close navigation" onClick={()=>setSidebar(false)}/>}
  <aside className={'sidebar '+(sidebar?'is-open':'')}>
   <button className="brand" onClick={()=>nav('overview')}><span className="brand-mark">k.</span><span>KCL study space<small>Cyber Security MSc</small></span></button>
    <div className="year-label">Academic year 2026 / 2027</div>
   <nav aria-label="Main navigation">{navItems.map(([id,I,label])=><button key={id} className={'nav-item '+(view===id?'active':'')} onClick={()=>nav(id)}><I size={18}/>{label}{id==='notes'&&data.notes_count>0&&<span className="nav-count">{data.notes_count}</span>}</button>)}</nav>
     <div className="sidebar-section">Modules</div>
    <div className="module-nav">{[[1,'Semester 1'],[2,'Semester 2'],[3,'Individual Project']].map(([term,label])=>{const open=openTerms[String(term)];return <section className="module-group" key={String(term)}><button className="module-group-toggle" aria-expanded={open} onClick={()=>setOpenTerms(x=>{const next={...x,[String(term)]:!open};localStorage.setItem('kcl-sidebar-terms',JSON.stringify(next));return next;})}>{label as string}<ChevronRight size={15}/></button>{open&&data.modules.filter(m=>m.term===term).map(m=><button key={m.id} onClick={()=>openModule(m.id)} className={view==='notebook'&&current.id===m.id?'selected':''}><Icon name={m.icon} size={17}/><span>{m.name}<small>{m.elective?'Optional':'Mandatory'}</small></span></button>)}</section>})}</div>
   <div className="sidebar-bottom"><div className="connection"><span className={'status-dot '+(data.model.ready?'ready':'')}/><span>{data.model.ready?'Luna connected':'Model needs attention'}<small>Runs through your Codex access</small></span></div><button className="nav-item" onClick={()=>nav('settings')}><Settings size={18}/>Settings and storage</button></div>
  </aside>
  <div className="workspace">
    <header className="topbar"><div className="breadcrumb"><button className="mobile-menu icon-button" onClick={()=>setSidebar(true)} aria-label="Open navigation"><Menu size={20}/></button><span>My workspace</span><ChevronRight size={16}/><strong>{view==='notebook'?current.name:navItems.find(n=>n[0]===view)?.[2]||'Settings'}</strong></div><div className="top-actions"><button className="icon-button" onClick={()=>nav('library')} aria-label="Search source library"><Search size={20}/></button></div></header>
   {error&&<div className="banner error" role="alert"><span>{error}</span><button aria-label="Dismiss error" onClick={()=>setError('')}><X size={16}/></button></div>}
   {notice&&<div className="toast" role="status"><CheckCircle2 size={18}/>{notice}</div>}
   <main className={'content '+(view==='notebook'?'notebook-content':'')}>
    {view==='overview'&&<Overview data={data} open={openModule} library={()=>nav('library')} guide={()=>nav('guide')} setError={setError}/>}
    {view==='notebook'&&<Notebook key={current.id} module={current} data={data} openSource={(id,page=1)=>setSource({id,page})} act={act} refresh={refresh} setError={setError} library={()=>nav('library')}/>}
    {view==='library'&&<SourceLibraryFull data={data} act={act} source={(id,page=1)=>setSource({id,page})}/>}
    {view==='guide'&&<GuideView/>}
    {view==='notes'&&<NotesView open={openModule}/>}
    {view==='settings'&&<SettingsView data={data} act={act}/>}
   </main>
   <footer className="app-footer"><span>Personal study companion · Course facts: {data.snapshot}</span><span>Local library. Selected excerpts go to Codex when you ask a question.</span></footer>
  </div>
  {source&&<SourceModal id={source.id} page={source.page} close={()=>setSource(null)}/>}
 </div>;
}

function Overview({data,open,library,guide,setError}:{data:Bootstrap;open:(id:string)=>void;library:()=>void;guide:()=>void;setError:(s:string)=>void}){
 const taught=data.modules.filter(m=>m.term<3);
 const project=data.modules.find(m=>m.term===3);
 return <>
   <div className="page-heading course-heading"><div><h1>MSc Cyber Security</h1><p>Your modules and your own course material, kept together on this computer.</p></div><div className="heading-actions"><button className="button" onClick={guide}><BookOpen size={18}/>Open course guide</button><button className="button primary" onClick={library}><Plus size={18}/>Add course material</button></div></div>
   <section className="programme-panel" aria-labelledby="programme-summary"><div className="programme-lead"><span className="programme-mark"><GraduationCap size={28}/></span><div><h2 id="programme-summary">Your programme at a glance</h2><p>Eight taught modules across two semesters, followed by the MSc Individual Project.</p></div></div><div className="programme-stats"><div><strong>180</strong><span>Total credits</span><small>120 taught + 60 project</small></div><div><strong>9</strong><span>Modules</span><small>Across the full programme</small></div><div><strong>1 year</strong><span>Full-time</span><small>September 2026 to August 2027</small></div><div><strong>Level 7</strong><span>Postgraduate</span><small>One listed module is at Level 6</small></div></div><div className="programme-foot"><div><span>Department</span><strong>Informatics</strong></div><div><span>Teaching pattern</span><strong>4 modules per semester</strong></div><div><span>Record snapshot</span><strong>{data.snapshot}</strong></div><button className="text-link" onClick={guide}>See programme information<ArrowRight size={18}/></button></div></section>
   <div className="section-intro"><div><h2>Study by semester</h2></div><p>Select a module to open its empty notebook and add your own sources.</p></div>
  <div className="overview-columns"><div className="module-sections">{[1,2].map(term=><section key={term} className="term-section"><div className="section-heading"><h2>Semester {term}</h2><span>{term===1?'Autumn':'Spring'} · 60 credits · 4 modules</span></div><div className="module-grid module-grid-four">{taught.filter(m=>m.term===term).map(m=><ModuleCard key={m.id} m={m} open={open}/>)}</div></section>)}{project&&<section className="term-section project-section"><div className="section-heading"><h2>MSc Individual Project</h2><span>February–September · 60 credits</span></div><button className="project-row" onClick={()=>open(project.id)}><span className="module-icon"><NotebookPen size={23}/></span><div><small>{project.id} · LEVEL {project.level}</small><h3>From a research question to your own contribution</h3><p>Keep your literature, methods, technical work and dissertation milestones connected.</p></div><span className="project-credit">60 credits</span><ArrowUpRight size={20}/></button></section>}</div>
   <aside className="overview-aside"><div className="library-summary"><Library size={22}/><h3>{data.sources.filter(s=>s.status==='Indexed').length} sources indexed locally</h3><p>Your library starts empty, so add the lectures, readings and notes that belong to you.</p><button className="text-link" onClick={library}>Open source library<ArrowRight size={18}/></button></div></aside></div>
   <GlobalChatWorkspace data={data} setError={setError}/>
  </>;
}

function GlobalChatWorkspace({data,setError}:{data:Bootstrap;setError:(s:string)=>void}){
 const [sessions,setSessions]=useState<ChatSession[]>([]),[active,setActive]=useState(''),[messages,setMessages]=useState<Message[]>([]),[selected,setSelected]=useState<string[]>([]),[question,setQuestion]=useState(''),[busy,setBusy]=useState(false);
 const load=async()=>{const s=await api<ChatSession[]>('/api/sessions?scope=global',undefined,'GET');setSessions(s);if(!active&&s[0])setActive(s[0].id);};useEffect(()=>{load().catch(e=>setError(e.message));},[]);useEffect(()=>{if(active){setSelected([]);api<Message[]>(`/api/sessions/${active}/messages`,undefined,'GET').then(setMessages).catch(e=>setError(e.message));}},[active]);
 async function create(){try{const s=await api<ChatSession>('/api/sessions',{scope:'global'});await load();setActive(s.id);return s;}catch(e){setError((e as Error).message);return null;}}
 async function ask(mode='explain'){if(!question.trim())return;let target=active;if(!target){const s=await create();if(!s)return;target=s.id;}setBusy(true);try{await api('/api/chat',{session_id:target,question,sources:selected,mode});setQuestion('');setMessages(await api(`/api/sessions/${target}/messages`,undefined,'GET'));await load();}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 const rename=(s:ChatSession)=>{const title=prompt('Rename chat',s.title);if(title)api(`/api/sessions/${s.id}`,{title},'PATCH').then(load).catch(e=>setError(e.message));};const remove=(s:ChatSession)=>{if(confirm('Delete this saved chat?'))api(`/api/sessions/${s.id}`,{},'DELETE').then(()=>{if(active===s.id){setActive('');setMessages([]);}return load();}).catch(e=>setError(e.message));};
 return <section className="global-chat"><div className="section-heading"><div><h2><MessageSquare size={21}/>Global workspace chat</h2><p>Use the course guide alone, or select personal and module sources explicitly.</p></div><button className="button primary" onClick={create}><Plus size={16}/>New chat</button></div><div className="saved-chat-layout"><aside className="saved-chats">{sessions.map(s=><div key={s.id} className={active===s.id?'active':''}><button onClick={()=>setActive(s.id)}>{s.title}</button><button aria-label={`Rename ${s.title}`} onClick={()=>rename(s)}><Pencil size={15}/></button><button aria-label={`Delete ${s.title}`} onClick={()=>remove(s)}><Trash2 size={15}/></button></div>)}</aside><div className="global-chat-main"><div className="global-sources">{[...data.modules.map(m=>[m.id,m.name]),['PERSONAL','Personal files']].map(([id,name])=>{const sources=data.sources.filter(s=>s.module===id);return sources.length?<fieldset key={id}><legend>{name}</legend>{sources.map(s=><label key={s.id}><input type="checkbox" checked={selected.includes(s.id)} onChange={e=>setSelected(x=>e.target.checked?[...x,s.id]:x.filter(v=>v!==s.id))}/>{s.title}</label>)}</fieldset>:null;})}</div>{active&&<><div className="conversation compact">{messages.map(m=>m.role==='user'?<div className="user-message" key={m.id}><p>{m.content.question}</p></div>:<article className="assistant-message" key={m.id}><Rich text={(m.content as Answer).answer||''}/></article>)}</div><div className="quick-actions"><button onClick={()=>ask('diagram')}><Sparkles size={15}/>Create a visual diagram</button><button onClick={()=>ask('quiz')}><CircleHelp size={15}/>Quiz me</button></div></>}<textarea value={question} onChange={e=>setQuestion(e.target.value)} placeholder="Ask about your programme or selected sources…"/><button className="button primary" disabled={busy||!question.trim()} onClick={()=>ask()}>{busy?'Working…':'Send question'}<Send size={16}/></button></div></div></section>;
}

function GlobalChat({data,setError}:{data:Bootstrap;setError:(s:string)=>void}){
 const [sessions,setSessions]=useState<ChatSession[]>([]),[active,setActive]=useState<string>(''),[messages,setMessages]=useState<Message[]>([]),[selected,setSelected]=useState<string[]>([]),[question,setQuestion]=useState(''),[busy,setBusy]=useState(false);
 const load=async()=>{const s=await api<ChatSession[]>('/api/sessions?scope=global',undefined,'GET');setSessions(s);if(!active&&s[0])setActive(s[0].id)};
 useEffect(()=>{load().catch(e=>setError(e.message));},[]);useEffect(()=>{if(active){setSelected([]);api<Message[]>(`/api/sessions/${active}/messages`,undefined,'GET').then(setMessages).catch(e=>setError(e.message));}},[active]);
 async function create(){try{const s=await api<ChatSession>('/api/sessions',{scope:'global'});await load();setActive(s.id);return s;}catch(e){setError((e as Error).message);return null;}}
 async function remove(id:string){if(!confirm('Delete this saved chat?'))return;try{await api(`/api/sessions/${id}`,{},'DELETE');setActive('');setMessages([]);await load();}catch(e){setError((e as Error).message);}}
 async function ask(mode='explain'){if(!question.trim())return;let target=active;if(!target){const session=await create();if(!session)return;target=session.id;}setBusy(true);try{await api('/api/chat',{session_id:target,question,sources:selected,mode});setQuestion('');setMessages(await api(`/api/sessions/${target}/messages`,undefined,'GET'));await load();}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 const groups=[...data.modules.map(m=>[m.id,m.name]),['PERSONAL','Personal files']] as string[][];
 return <section className="global-chat" aria-labelledby="global-chat-title"><div className="section-heading"><div><h2 id="global-chat-title"><MessageSquare size={21}/>Global workspace chat</h2><p>Use the course guide and the personal or module sources you explicitly select.</p></div><button className="button primary" onClick={create}><Plus size={16}/>New chat</button></div><div className="saved-chat-layout"><aside className="saved-chats" aria-label="Saved global chats">{sessions.length===0?<p className="small-muted">No saved chats yet.</p>:sessions.map(s=><div key={s.id} className={active===s.id?'active':''}><button onClick={()=>setActive(s.id)}>{s.title}</button><button aria-label={`Delete ${s.title}`} onClick={()=>remove(s.id)}><Trash2 size={15}/></button></div>)}</aside><div className="global-chat-main">{!active?<div className="empty-state"><MessageSquare size={28}/><h2>Start a clean global chat.</h2><p>Select sources across your modules or Personal files when you are ready.</p></div>:<><div className="global-sources">{groups.map(([id,name])=>{const items=data.sources.filter(s=>s.module===id);return items.length?<fieldset key={id}><legend>{name}</legend>{items.map(s=><label key={s.id}><input type="checkbox" checked={selected.includes(s.id)} onChange={e=>setSelected(x=>e.target.checked?[...x,s.id]:x.filter(i=>i!==s.id))}/>{s.title}</label>)}</fieldset>:null;})}</div><div className="conversation compact">{messages.length===0?<p className="small-muted">This saved chat is empty.</p>:messages.map(m=>m.role==='user'?<div className="user-message" key={m.id}><p>{m.content.question}</p></div>:<article className="assistant-message" key={m.id}><Rich text={(m.content as Answer).answer||''}/></article>)}</div><div className="quick-actions"><button onClick={()=>ask('diagram')}><Sparkles size={15}/>Create a visual diagram</button><button onClick={()=>ask('quiz')}><CircleHelp size={15}/>Quiz me</button></div><textarea value={question} onChange={e=>setQuestion(e.target.value)} placeholder="Ask about your programme or selected sources…"/><button className="button primary" disabled={busy||!question.trim()||!selected.length} onClick={()=>ask()}>{busy?'Working…':'Send question'}<Send size={16}/></button></>}</div></div></section>
}

function ModuleCard({m,open}:{m:Module;open:(id:string)=>void}){return <article className="module-card"><div className="card-top"><span className="module-icon"><Icon name={m.icon} size={22}/></span><span className="credit-label">Level {m.level} · {m.credits} credits</span></div><div className="module-code">{m.id}</div><h3>{m.name}</h3><p>{m.description}</p><div className="card-bottom"><div className="source-count"><FileText size={17}/>{m.sources} indexed {m.sources===1?'source':'sources'}<span>{m.credits*10}h notional workload</span></div><button className="open-module" onClick={()=>open(m.id)} aria-label={`Open ${m.name} notebook`}>Open notebook<ArrowUpRight size={19}/></button></div></article>;}

type Act=(fn:()=>Promise<unknown>,success?:string)=>Promise<void>;
function Notebook({module:m,data,openSource,act,refresh,setError,library}:{module:Module;data:Bootstrap;openSource:(id:string,page?:number)=>void;act:Act;refresh:()=>Promise<void>;setError:(s:string)=>void;library:()=>void}){
 const sources=data.sources.filter(s=>s.module===m.id);
  const [selected,setSelected]=useState<string[]>([]),[question,setQuestion]=useState(''),[messages,setMessages]=useState<Message[]>([]),[busy,setBusy]=useState(false),[tab,setTab]=useState('chat'),[loading,setLoading]=useState(true),[mobileSources,setMobileSources]=useState(false),[sessions,setSessions]=useState<ChatSession[]>([]),[sessionId,setSessionId]=useState('');
 const end=useRef<HTMLDivElement>(null);
  const loadSessions=async()=>{const s=await api<ChatSession[]>(`/api/sessions?scope=module&module_id=${m.id}`,undefined,'GET');setSessions(s);if(!sessionId&&s[0])setSessionId(s[0].id);};
  useEffect(()=>{loadSessions().catch(e=>setError(e.message)).finally(()=>setLoading(false));},[m.id]);
  useEffect(()=>{if(sessionId){setSelected([]);api<Message[]>(`/api/sessions/${sessionId}/messages`,undefined,'GET').then(setMessages).catch(e=>setError(e.message));}else setMessages([]);},[sessionId]);
  async function newChat(){try{const s=await api<ChatSession>('/api/sessions',{scope:'module',module:m.id});await loadSessions();setSessionId(s.id);return s;}catch(e){setError((e as Error).message);return null;}}
  async function deleteChat(){if(!sessionId||!confirm('Delete this saved chat?'))return;try{await api(`/api/sessions/${sessionId}`,{},'DELETE');setSessionId('');await loadSessions();}catch(e){setError((e as Error).message);}}
 async function ask(text=question,mode='explain'){
  if(!text.trim()||busy)return;setQuestion('');setBusy(true);setError('');
   try{let target=sessionId;if(!target){const session=await newChat();if(!session)return;target=session.id;}await api<Answer>('/api/chat',{session_id:target,question:text,sources:selected,mode});setMessages(await api<Message[]>(`/api/sessions/${target}/messages`,undefined,'GET'));await loadSessions();await refresh();setTimeout(()=>end.current?.scrollIntoView({behavior:'smooth',block:'nearest'}),100);}
  catch(e){setError((e as Error).message);setQuestion(text);}finally{setBusy(false);}
 }
 return <><div className="notebook-heading"><div><div className="module-meta"><BookOpen size={18}/>{m.id} · {m.credits} credits</div><h1>{m.name}</h1><p>{m.description}</p></div></div>
 <div className="tabs" aria-label="Module views">{[['chat','Notebook'],...(m.id==='7CCSMCIS'?[['lab','Visual lab']]:[])].map(([id,label])=><button key={id} className={tab===id?'active':''} onClick={()=>setTab(id)}>{label}</button>)}<button className="source-toggle" onClick={()=>setMobileSources(!mobileSources)}><Library size={17}/>Sources ({sources.length})</button></div>
 {tab==='chat'?<div className="notebook-layout"><aside className={'sources-panel '+(mobileSources?'mobile-visible':'')}><div className="panel-heading"><h3>Sources</h3><button className="icon-button" onClick={library} aria-label="Add source"><Plus size={19}/></button></div><p className="small-muted">Choose the material for this conversation.</p>{sources.length===0&&<div className="source-empty"><FolderOpen size={22}/><p>No files have been added to this module.</p></div>}{sources.map(s=><div className="source-option" key={s.id}><input aria-label={`Use ${s.title}`} type="checkbox" disabled={s.status!=='Indexed'} checked={selected.includes(s.id)} onChange={e=>setSelected(old=>e.target.checked?[...old,s.id]:old.filter(i=>i!==s.id))}/><button onClick={()=>openSource(s.id)}><FileText size={19}/><span>{s.title}<small>{s.pages} {s.pages===1?'page':'pages'} · {s.status}</small></span></button></div>)}<div className="sources-foot">{selected.length} sources selected<br/><span>Search runs locally. Relevant excerpts are sent with your question.</span></div><button className="button full-width" onClick={library}><Plus size={17}/>Add material</button></aside>
  <section className="chat-panel"><div className="chat-top"><span><Brain size={16}/>Luna · revision tutor</span><span className="small-muted">Cited answers from selected sources</span></div><div className="module-chat-controls"><select aria-label="Saved chats" value={sessionId} onChange={e=>setSessionId(e.target.value)}><option value="">Select a saved chat</option>{sessions.map(s=><option key={s.id} value={s.id}>{s.title}</option>)}</select><button className="text-link" onClick={newChat}><Plus size={15}/>New chat</button>{sessionId&&<button className="text-link" onClick={()=>{const title=prompt('Rename chat',sessions.find(s=>s.id===sessionId)?.title||'');if(title)api(`/api/sessions/${sessionId}`,{title},'PATCH').then(loadSessions).catch(e=>setError(e.message));}}><Pencil size={14}/>Rename</button>}{sessionId&&<button className="text-link" onClick={deleteChat}><Trash2 size={14}/>Delete</button>}</div>
  <div className="conversation">{loading?<div className="empty-state"><Loader2 className="spin"/>Loading conversation…</div>:messages.length===0?<div className="chat-welcome"><span className="welcome-icon"><Icon name={m.icon} size={30}/></span><h2>This notebook is empty.</h2><p>{sources.length===0?'Add your own module files, then select the sources you want Luna to use.':'Select one or more sources, then write your own question below.'}</p>{sources.length===0&&<button className="button primary" onClick={library}><Plus size={18}/>Add module files</button>}</div>:messages.map(msg=>msg.role==='user'?<div key={msg.id} className="user-message"><span>You</span><p>{msg.content.question}</p></div>:<AnswerView key={msg.id} answer={msg.content as Answer} module={m.id} source={openSource} act={act} follow={q=>ask(q)}/>)}
  {busy&&<div className="thinking" role="status"><Loader2 size={17} className="spin"/><div>Luna is working through the sources.<small>Preparing an explanation and checking the requested response format.</small></div></div>}<div ref={end}/></div>
  <form className="composer" onSubmit={e=>{e.preventDefault();ask();}}><label className="sr-only" htmlFor="question">Ask about this module</label><textarea id="question" value={question} onChange={e=>setQuestion(e.target.value)} placeholder={`Ask about ${m.name.toLowerCase()}…`} rows={2} maxLength={5000} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();ask();}}}/><div className="composer-bottom"><span>{selected.length} selected sources · Luna</span><button className="send-button" type="submit" aria-label="Send question" disabled={busy||!question.trim()||!selected.length}>{busy?<Loader2 size={18} className="spin"/>:<Send size={18}/>}</button></div></form><div className="composer-note">Check cited passages when an answer matters. Enter to send; Shift + Enter for a new line.</div>
 </section></div>:<VisualLab/>}
 </>;
}

function AnswerView({answer:a,module,source,act,follow}:{answer:Answer;module:string;source:(id:string,page?:number)=>void;act:Act;follow:(q:string)=>void}){
 const [choice,setChoice]=useState<number|null>(null),[revealed,setRevealed]=useState(false);
 return <article className="assistant-message"><div className="answer-label"><span className="answer-mark"><Bot size={20}/></span><strong>Study tutor</strong><small>Luna</small></div><Rich text={a.answer}/>
 {a.citations?.length>0&&<div className="citation-list">{a.citations.map(c=><button key={c.ref} onClick={()=>source(c.source_id,c.page)}><span>{c.ref}</span>{c.title}<small>p. {c.page}</small><ArrowUpRight size={12}/></button>)}</div>}
 {!a.grounded&&<p className="small-muted">This answer did not include a supporting citation. Check the selected material.</p>}
 {a.diagram?.nodes?.length>1&&<div className="lesson-diagram"><h3 className="icon-heading"><GitBranch size={20}/>{a.diagram.title}</h3><div className="concept-nodes">{a.diagram.nodes.map((n,i)=><button key={i} onClick={()=>follow(`Explain ${n} in more detail and how it connects to the previous explanation.`)}><span>{i+1}</span>{n}</button>)}</div><div className="concept-edges">{a.diagram.connections.map((e,i)=><div key={i}><span>{a.diagram.nodes[e.from]}</span><ArrowRight size={17}/><span>{a.diagram.nodes[e.to]}</span><small>{e.label}</small></div>)}</div></div>}
 {a.quiz?.question&&<div className="quiz-panel"><h3 className="icon-heading"><CircleHelp size={20}/>Check your understanding</h3><p className="quiz-question">{a.quiz.question}</p><div className="quiz-choices">{a.quiz.choices.map((q,i)=><button key={i} className={(choice===i?'chosen ':'')+(revealed&&i===a.quiz.answer?'correct':'')} onClick={()=>{setChoice(i);setRevealed(false);}}><span>{String.fromCharCode(65+i)}</span>{q}</button>)}</div><button className="button" disabled={choice===null} onClick={()=>setRevealed(true)}>Check answer</button>{revealed&&<div className="quiz-feedback" role="status"><strong>{choice===a.quiz.answer?'That is correct.':'Have another look at this step.'}</strong><p>{a.quiz.explanation}</p></div>}</div>}
 <div className="answer-actions"><button className="text-link" onClick={()=>act(()=>api('/api/notes',{module,title:a.answer.replace(/[#*]/g,'').slice(0,100),content:a.answer+'\n\n### Sources\n\n'+(a.citations||[]).map(c=>'['+c.ref+': '+c.title.replace(/[\[\]]/g,'')+', p. '+c.page+'](/api/sources/'+c.source_id+'/file#page='+c.page+')').join('\n\n')}),'Saved to your notes.')}><Bookmark size={15}/>Save explanation</button></div>
 {a.followups?.length>0&&<div className="followups">{a.followups.map((q,i)=><button key={i} onClick={()=>follow(q)}>{q}<ArrowRight size={13}/></button>)}</div>}
 </article>;
}

function VisualLab(){
 const [p,setP]=useState(5),[q,setQ]=useState(11),[message,setMessage]=useState(7),[step,setStep]=useState(0);
 const n=p*q,phi=(p-1)*(q-1);const gcd=(a:number,b:number):number=>b?gcd(b,a%b):a;let e=3;while(gcd(e,phi)!==1)e+=2;let d=1;while(e*d%phi!==1)d++;
 const power=(base:number,exponent:number,mod:number)=>{let b=BigInt(base),ex=BigInt(exponent),r=1n,m=BigInt(mod);while(ex>0n){if(ex&1n)r=r*b%m;b=b*b%m;ex>>=1n;}return Number(r);};
 const m=Math.min(message,n-1),cipher=power(m,e,n),plain=power(cipher,d,n);
 const stages=[['Choose two primes',`p = ${p}, q = ${q}`,`The two primes define the number system used by this small example.`],['Build the modulus',`n = ${p} × ${q} = ${n}`,`For distinct primes, φ(n) = (${p} − 1) × (${q} − 1) = ${phi}.`],['Connect the keys',`e = ${e}, d = ${d}`,`${e} × ${d} mod ${phi} = 1. The private exponent is a multiplicative inverse.`],['Encrypt the message',`${m}^${e} mod ${n} = ${cipher}`,`The public exponent transforms the message into the ciphertext ${cipher}.`],['Recover the message',`${cipher}^${d} mod ${n} = ${plain}`,`The private exponent recovers the original message, ${plain}.`]];
 return <section className="visual-lab"><div className="lab-intro"><div className="eyebrow">CRYPTOGRAPHY / INTERACTIVE PREPARATION</div><h2>See how the two keys connect.</h2><p>Change the values and follow a small RSA example. Every calculation runs locally.</p></div><div className="lab-controls"><label>Prime p<select aria-label="Prime p" value={p} onChange={event=>{setP(Number(event.target.value));setStep(0);}}>{[3,5,7].map(v=><option key={v}>{v}</option>)}</select></label><label>Prime q<select aria-label="Prime q" value={q} onChange={event=>{setQ(Number(event.target.value));setStep(0);}}>{[11,13,17].map(v=><option key={v}>{v}</option>)}</select></label><label className="message-range">Message: <strong>{m}</strong><input aria-label="Message value" type="range" min={0} max={n-1} value={m} onChange={event=>setMessage(Number(event.target.value))}/></label></div><div className="rsa-flow"><div><span>Original message</span><strong>{m}</strong><small>Plaintext</small></div><div className="flow-operation"><span>Public key ({n}, {e})</span><ArrowRight/><small>Encrypt</small></div><div className="cipher"><span>Encrypted value</span><strong>{cipher}</strong><small>Ciphertext</small></div><div className="flow-operation"><span>Private exponent {d}</span><ArrowRight/><small>Decrypt</small></div><div><span>Recovered message</span><strong>{plain}</strong><small>Matches the original</small></div></div><div className="lab-stepper"><div className="stepper-track">{stages.map((s,i)=><button key={i} className={i===step?'active':''} onClick={()=>setStep(i)}><span>{i+1}</span>{s[0]}</button>)}</div><div className="step-detail" aria-live="polite"><small>STEP {step+1} OF 5</small><h3>{stages[step][0]}</h3><div className="equation">{stages[step][1]}</div><p>{stages[step][2]}</p><div className="step-buttons"><button className="button" disabled={step===0} onClick={()=>setStep(step-1)}><ChevronLeft size={15}/>Previous</button><button className="button primary" disabled={step===4} onClick={()=>setStep(step+1)}>Next step<ChevronRight size={15}/></button></div></div></div><p className="lab-note">A learning illustration using tiny primes and textbook RSA. Real encryption requires secure parameters, padding and a suitable implementation. Source: the local “Modular arithmetic and RSA” preparation notes.</p></section>;
}

function SourceLibraryFull({data,act,source}:{data:Bootstrap;act:Act;source:(id:string,page?:number)=>void}){
 const [code,setCode]=useState('7CCSMCIS'),[filter,setFilter]=useState('all'),[url,setUrl]=useState(''),[signed,setSigned]=useState(false),[query,setQuery]=useState(''),[results,setResults]=useState<Citation[]|null>(null),[uploading,setUploading]=useState(false);const fileInput=useRef<HTMLInputElement>(null);
 const label=(id:string)=>id==='PERSONAL'?'Personal documents':data.modules.find(m=>m.id===id)?.name||id;
 async function upload(files:FileList|null){if(!files?.length)return;setUploading(true);await act(async()=>{for(const file of Array.from(files)){const form=new FormData();form.append('file',file);await api(`/api/modules/${code}/upload`,form);}},'Documents added to the local library.');setUploading(false);if(fileInput.current)fileInput.current.value='';}
 return <><div className="page-heading"><div><h1>Start with the source.</h1><p>Collect module material or keep personal documents in their separate folder.</p></div><button className="button" onClick={()=>act(()=>api('/api/scan',{}),'Checking local source folders.')}><RefreshCw size={16}/>Scan local folders</button></div><div className="import-panel"><div><h2>Add local material</h2><label className="field-label">Library folder<select value={code} onChange={e=>setCode(e.target.value)}><option value="PERSONAL">Personal documents</option>{data.modules.map(m=><option key={m.id} value={m.id}>{m.name}</option>)}</select></label><input ref={fileInput} className="sr-only" type="file" multiple accept=".pdf,.md,.txt" onChange={e=>upload(e.target.files)}/><button className="button" disabled={uploading} onClick={()=>fileInput.current?.click()}><Plus size={16}/>Choose local files</button></div>{code!=='PERSONAL'&&<div className="import-web"><h2>Collect from KEATS</h2><label className="field-label">Module page or direct PDF URL<input type="url" value={url} onChange={e=>setUrl(e.target.value)} placeholder="https://keats.kcl.ac.uk/…"/></label><div className="import-options"><label><input type="checkbox" checked={signed} onChange={e=>setSigned(e.target.checked)}/>Use my study-browser sign-in</label><button className="text-link" onClick={()=>act(()=>api('/api/browser/login',{}),'Study browser opened. Sign in, close it, then collect the page.')}><ExternalLink size={14}/>Sign into KEATS</button></div><button className="button primary" disabled={!url.trim()} onClick={()=>act(async()=>{await api('/api/collect',{module:code,url,signed_in:signed});setUrl('');},'Collection started. Progress will appear below.')}><Download size={16}/>Collect PDFs</button><small>The collector follows accessible PDFs and Moodle resource folders.</small></div>}</div><div className="library-toolbar"><select aria-label="Filter sources by module" value={filter} onChange={e=>{setFilter(e.target.value);setResults(null);}}><option value="all">All sources</option><option value="PERSONAL">Personal documents</option>{data.modules.map(m=><option key={m.id} value={m.id}>{m.name}</option>)}</select><form onSubmit={e=>{e.preventDefault();const target=filter==='all'?code:filter;act(async()=>setResults(await api(`/api/search?module_id=${target}&q=${encodeURIComponent(query)}`,undefined,'GET')));}}><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder={`Search ${label(filter==='all'?code:filter)}…`}/><button type="submit">Search</button></form></div>{results&&<div className="search-results">{results.map((r,i)=><button key={i} onClick={()=>source(r.source_id,r.page)}><strong>{r.title} · page {r.page}</strong><p>{r.text.slice(0,300)}…</p></button>)}</div>}<div className="source-table"><div className="source-table-head"><span>Document</span><span>Folder</span><span>Status</span></div>{data.sources.filter(s=>filter==='all'||s.module===filter).map(s=><button className="source-table-row" key={s.id} onClick={()=>source(s.id)}><div><FileText size={20}/><span><strong>{s.title}</strong><small>{s.pages} pages</small></span></div><span>{label(s.module)}</span><span className="source-status">{s.status}<ArrowUpRight size={14}/></span></button>)}</div></>;
}

