 const [filter,setFilter]=useState('all'),[code,setCode]=useState('7CCSMCIS'),[url,setUrl]=useState(''),[signed,setSigned]=useState(false),[uploading,setUploading]=useState(false),[query,setQuery]=useState(''),[results,setResults]=useState<Citation[]|null>(null);
