 {data.jobs.length>0&&<section className="jobs"><div className="section-heading"><h2>Recent imports</h2><small>Updates every 10 seconds</small></div>{data.jobs.slice(0,5).map(j=><div className="job" key={j.id}><span className={'job-state '+(j.status==='Complete'?'success':'')}>{['Queued','Collecting','Indexing'].includes(j.status)?<Loader2 size={14} className="spin"/>:<FileText size={14}/>} {j.status}</span><span>{j.detail}</span></div>)}</section>}
 <div className="library-toolbar"><select aria-label="Filter sources by module" value={filter} onChange={e=>{setFilter(e.target.value);setResults(null);}}><option value="all">All modules</option>{data.modules.map(m=><option key={m.id} value={m.id}>{m.name}</option>)}</select><form onSubmit={e=>{e.preventDefault();act(async()=>setResults(await api(`/api/search?module_id=${filter==='all'?code:filter}&q=${encodeURIComponent(query)}`)));}}><Search size={16}/><input aria-label="Search passages" value={query} onChange={e=>setQuery(e.target.value)} placeholder={`Search ${data.modules.find(m=>m.id===(filter==='all'?code:filter))?.name}…`}/><button type="submit">Search</button></form></div>
