function GuideView(){const [text,setText]=useState('');useEffect(()=>{api('/api/guide').then(d=>setText(d.content)).catch(e=>setText(e.message));},[]);const parts=text.split(/^## /m);const intro=parts.shift()||'';const tileIcons=[GraduationCap,BookOpen,Library,FolderOpen,Calendar,ShieldCheck];return <><div className="page-heading"><div><h1>Your course guide</h1><p>Programme information arranged for quick reference.</p></div></div>{intro&&<div className="guide-intro"><Rich text={intro}/></div>}<div className="guide-grid">{parts.map((part,i)=>{const [title,...body]=part.split('\n');const I=tileIcons[i%tileIcons.length];return <details className="guide-tile" key={title} open={i<3}><summary><I size={22}/><span>{title}</span><ChevronRight size={18}/></summary><Rich text={body.join('\n')}/></details>})}</div></>}
function NotesView({open}:{open:(id:string)=>void}){const [notes,setNotes]=useState<{id:number;module:string;title:string;content:string}[]>([]);useEffect(()=>{api('/api/notes').then(setNotes);},[]);return <><div className="page-heading"><div><h1>Your revision notes.</h1><p>Explanations you have chosen to keep, stored on your machine.</p></div></div>{notes.length===0?<div className="empty-state"><Bookmark size={30}/><h2>Keep the explanations that help.</h2><p>Choose “Save explanation” underneath a chat answer to add it here.</p></div>:notes.map(n=><article className="saved-note" key={n.id}><div className="section-heading"><small>{n.module}</small><button className="text-link" onClick={()=>open(n.module)}>Open module<ArrowUpRight size={15}/></button></div><Rich text={n.content}/></article>)}</>;}
function SettingsView({data,act}:{data:Bootstrap;act:Act}){return <><div className="page-heading"><div><div className="eyebrow">YOUR PERSONAL SETUP</div><h1>Local, with room to grow.</h1><p>Your course library and study history belong to this machine.</p></div></div><div className="settings-grid"><section className="settings-panel"><Brain size={24}/><h2>Luna for everyday revision</h2><p>{data.model.detail}</p><dl><dt>Model</dt><dd>{data.model.model}</dd><dt>Connection</dt><dd>Official local Codex App Server</dd><dt>Reasoning</dt><dd>Medium</dd><dt>Billing</dt><dd>{data.model.auth==='chatgpt'?'Your Codex plan allowance applies':'Check your active Codex authentication'}</dd></dl><button className="button" onClick={()=>act(()=>api('/api/model/reconnect',{}),'Model connection checked.')}><RefreshCw size={15}/>Check connection</button></section><section className="settings-panel"><FolderOpen size={24}/><h2>Files on your PC</h2><dl><dt>Study database and runtime</dt><dd className="path-text">{data.data_path}</dd><dt>Source documents</dt><dd className="path-text">{data.source_path}</dd><dt>Search</dt><dd>{data.retrieval}</dd></dl><p className="small-muted">The source folder is in your existing OneDrive checkout and may sync through OneDrive. The runtime database is outside that folder.</p><a className="button" href="/api/export" download><Download size={15}/>Export notes, chats and progress</a></section><section className="settings-panel"><ShieldCheck size={24}/><h2>What is sent to the model</h2><p>Your question, a short conversation context and relevant passages from the sources you select. The app does not upload your entire library.</p><p>Study mode disables shell tools, connectors and file editing. The model produces explanations and visual specifications; trusted app components render them.</p></section><section className="settings-panel"><BookOpen size={24}/><h2>Current build</h2><p>Embedded chat, source collection, local PDF imports, citations, saved notes and preparation tracking are working features.</p><p className="small-muted">Current weekly teaching plans need importing. Scanned PDFs requiring OCR are flagged. Semantic retrieval and unattended scheduled collection are planned next.</p></section></div></>;}
function SourceModal({id,page,close}:{id:string;page:number;close:()=>void}){const [source,setSource]=useState<{title:string;text:string;pdf:boolean;pages:number;warning:string;origin:string}|null>(null);useEffect(()=>{api(`/api/sources/${id}?page=${page}`).then(setSource);const key=(e:KeyboardEvent)=>{if(e.key==='Escape')close();};window.addEventListener('keydown',key);return ()=>window.removeEventListener('keydown',key);},[id,page]);return <div className="modal-backdrop" onClick={close}><section className="source-modal" role="dialog" aria-modal="true" aria-label="Source document" onClick={e=>e.stopPropagation()}><header><div><small>LOCAL SOURCE · PAGE {page}</small><h2>{source?.title||'Loading source'}</h2></div><button className="icon-button" onClick={close} aria-label="Close source"><X size={21}/></button></header>{source?.warning&&<p className="source-warning">{source.warning}</p>}<div className="source-preview">{source?.pdf?<iframe title={source.title} src={`/api/sources/${id}/file#page=${page}`}/>:<Rich text={source?.text||'Loading passage…'}/>}</div><footer><small>{source?.origin}</small><a className="button" href={`/api/sources/${id}/file#page=${page}`} target="_blank" rel="noreferrer">Open original<ArrowUpRight size={15}/></a></footer></section></div>;}

createRoot(document.getElementById('root')!).render(<App/>);
